<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{InventoryItem,PurchaseRequisition,Store};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class RequisitionController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('procurement.requisitions.index',['rows'=>PurchaseRequisition::with(['items.inventoryItem','store'])->where('property_id',$p)->latest()->paginate(30),'stores'=>Store::where('property_id',$p)->where('is_active',1)->get(),'items'=>InventoryItem::where('property_id',$p)->where('is_active',1)->orderBy('name')->get()]);}public function store(Request $r){$d=$r->validate(['store_id'=>'nullable|integer','department'=>'nullable|max:100','priority'=>'required|in:low,normal,high,urgent','reason'=>'nullable','inventory_item_id'=>'required|array|min:1','inventory_item_id.*'=>'required|integer','quantity'=>'required|array','quantity.*'=>'required|numeric|min:0.0001','estimated_unit_cost'=>'nullable|array']);DB::transaction(function()use($d){$p=auth()->user()->property_id;$req=PurchaseRequisition::create(['property_id'=>$p,'store_id'=>$d['store_id']??null,'number'=>'PR-'.now()->format('Ymd-His').'-'.random_int(10,99),'department'=>$d['department']??null,'priority'=>$d['priority'],'status'=>'submitted','reason'=>$d['reason']??null,'requested_by'=>auth()->id(),'submitted_at'=>now()]);foreach($d['inventory_item_id'] as $i=>$itemId)$req->items()->create(['inventory_item_id'=>$itemId,'quantity'=>$d['quantity'][$i],'estimated_unit_cost'=>$d['estimated_unit_cost'][$i]??0]);});return back()->with('success','Purchase requisition submitted.');}public function approve(PurchaseRequisition $requisition){abort_unless($requisition->property_id===auth()->user()->property_id,403);$requisition->update(['status'=>'approved','approved_by'=>auth()->id(),'approved_at'=>now()]);return back()->with('success','Requisition approved.');}}